function applyConstraintResult(index){const row=constraintViews[index];if(!row||!row.best)return;currentAsset={...row.asset};bars=row.bars;activeTrendResult=row;const option=[...$('assetSelect').options].find(x=>x.value===row.asset.code);if(option)$('assetSelect').value=row.asset.code;else $('assetSelect').selectedIndex=-1;updateAssetMeta(!option);$('source').className='source';$('source').innerHTML='<i></i><span>30%回撤多模型择优 · 训练期冻结参数 · 真实行情</span>';renderTrendWorkspace(row);window.scrollTo({top:document.querySelector('.workspace').offsetTop-75,behavior:'smooth'})}

function renderTrendWorkspace(row){const result=row.full,p=row.best.params,config=cfg();$('assetTitle').innerHTML=`${esc(row.asset.name)} <span>${esc(row.asset.code)}</span>`;$('periodLabel').textContent=`30%回撤多模型择优 · ${trendCoreText(p)} · ${config.start} 至 ${config.end}`;$('strategyNote').innerHTML=`<b>${TREND_MODEL_MAP[p.model]?.name||'增强模型'}</b> · 上升阶段保持高仓位，转弱后降仓；保护触发后先反弹回补，再确认满仓，可重复买卖。<br><span>${trendCoreText(p)}</span>`;$('metrics').innerHTML=[['策略净收益',pct(result.ret),result.ret>=0?'up':'down','期末 '+money(result.equity.at(-1)?.equity||config.capital)],['100%买入持有',pct(result.bret),result.bret>=0?'gold':'down','同费率滑点 · 首个可交易日买入'],['超额收益',pct(result.excess),result.excess>=0?'up':'down','策略减去100%持有'],['策略最大回撤',pct(result.dd),'down','上限 '+pct(row.maxDD)],['持有最大回撤',pct(result.bmdd),'gold','回撤改善 '+pct(result.ddImprove)],['年化 Sharpe',result.sharpe.toFixed(2),result.sharpe>=result.bmsh?'up':'','持有 '+result.bmsh.toFixed(2)],['综合评分',row.score.toFixed(1),row.qualifies?'up':'gold',`${row.stability.passes}/${row.stability.total}段同时正收益并跑赢`],['调仓 / 换手',result.adjustments+' 次','',`平均仓位 ${(result.exposure*100).toFixed(0)}% · 换手 ${result.turnover.toFixed(1)}×`]].map(x=>`<article class="metric"><span>${x[0]}</span><b class="${x[2]}">${x[1]}</b><small>${x[3]}</small></article>`).join('');const pass=row.qualifies;$('verdict').className='verdict show '+(pass?'pass':'fail');$('verdict').innerHTML=`<b>${pass?'严格通过：三段均正收益、跑赢持有且回撤达标':'未通过：至少一个历史硬门槛未满足'}</b><span>样本外收益 ${pct(row.oos.ret)} · 超额 ${pct(row.oos.excess)} · 回撤 ${pct(row.oos.dd)} · 综合分 ${row.score.toFixed(1)}</span>`;draw(result.equity);$('stabilityScore').className='stabilityScore '+(row.stability.passes>=3?'up':row.stability.passes>=2?'gold':'down');$('stabilityScore').textContent=`${row.stability.passes} / ${row.stability.total} 段同时正收益并跑赢`;$('windowGrid').innerHTML=row.stability.results.map((x,i)=>`<article class="windowCard ${x.result.ret>0&&x.result.excess>0?'pass':'fail'}"><span>固定参数窗口 ${i+1} · ${x.start.slice(2)}—${x.end.slice(2)}</span><b class="${x.result.excess>=0?'up':'down'}">${pct(x.result.excess)}</b><small>策略 ${pct(x.result.ret)} · 持有 ${pct(x.result.bret)}<br>最大回撤 ${pct(x.result.dd)}</small></article>`).join('');$('tradebox').innerHTML=result.trades.length?'<div class="trendTradeHead"><span>日期</span><span>动作</span><span>成交价</span><span>数量</span><span>仓位变化</span><span>原因</span></div>'+result.trades.slice(-12).reverse().map(t=>`<div class="trendTradeRow"><span>${t.date}</span><b class="${t.action==='加仓'?'up':'gold'}">${t.action}</b><span>${t.price.toFixed(2)}</span><span>${Math.round(t.shares).toLocaleString()}</span><span>${Math.round(t.from*100)}% → ${Math.round(t.to*100)}%</span><span>${t.reason}</span></div>`).join(''):'<div class="empty">当前配置没有发生有效调仓。</div>';window.currentResult=result}

async function runConstraint(){const selected=[...$('universe').querySelectorAll('input:checked')].map(input=>ASSETS.find(x=>x.code===input.value)),button=$('runConstraint'),status=$('constraintStatus'),maxDD=Math.min(.4,Math.max(.05,(+$('maxDrawdown').value||30)/100)),ratio=Math.min(.85,Math.max(.5,(+$('constraintSplit').value||70)/100)),config=cfg();if(!selected.length){status.className='validationStatus';status.textContent='请先在候选池至少勾选一个标的。';return}if(!config.start||!config.end||config.start>config.end){status.className='validationStatus';status.textContent='日期范围无效。';return}constraintRows=[];constraintViews=[];constraintData=null;constraintCancelled=false;activeTrendResult=null;button.disabled=true;button.classList.add('busy');button.lastElementChild.textContent='⟳';$('constraintProgress').style.width='0';status.className='validationStatus busy';status.textContent=`准备搜索 ${selected.length} 个标的的四类趋势模型…`;renderConstraint();let done=0,totalSearch=0;for(let startIndex=0;startIndex<selected.length&&!constraintCancelled;startIndex+=2){const chunk=selected.slice(startIndex,startIndex+2),loaded=await Promise.all(chunk.map(async asset=>{try{const data=await getDataRetry(asset,config.start,config.end);return{asset:{...asset,name:data.name},bars:data.bars}}catch(error){return{asset,error:String(error)}}}));for(const item of loaded){if(item.error)constraintRows.push(item);else{status.textContent=`分阶段优化 ${item.asset.name} · ${done+1}/${selected.length}`;try{const row=await optimizeConstraintAsset(item.bars,item.asset,{start:config.start,end:config.end,ratio,maxDD});constraintRows.push(row);totalSearch+=row.searched||0}catch(error){constraintRows.push({asset:item.asset,error:String(error)})}}done++;$('constraintProgress').style.width=(done/selected.length*100)+'%';renderConstraint();await delay(80)}}button.disabled=false;button.classList.remove('busy');button.lastElementChild.textContent='↗';const passed=constraintViews.filter(x=>x.qualifies).length;status.className='validationStatus done';status.textContent=`多模型优化完成 · ${constraintRows.length} 个标的 · ${totalSearch.toLocaleString()} 组训练配置 · ${passed} 个候选同时满足正收益、跑赢持有与回撤上限。`}

function addMonths(date,months){const value=new Date(date+'T00:00:00Z');value.setUTCMonth(value.getUTCMonth()+months);return value.toISOString().slice(0,10)}
function previousDay(date){const value=new Date(date+'T00:00:00Z');value.setUTCDate(value.getUTCDate()-1);return value.toISOString().slice(0,10)}
function resetValidation(){$('validationSummary').innerHTML='<div class="empty">运行后显示样本内最优参数与样本外表现。</div>';$('heatmap').innerHTML='';$('walkTable').innerHTML=''}

function renderHeatmap(id,cells,best){const grid=PARAM_GRID[id],cellMap=new Map(cells.map(x=>[`${x.x}|${x.y}`,x]));$('heatmap').style.gridTemplateColumns=`90px repeat(${grid.x.values.length},1fr)`;$('heatmap').innerHTML=`<div class="heatLabel">${grid.y.label} \ ${grid.x.label}</div>${grid.x.values.map(x=>`<div class="heatLabel">${x}</div>`).join('')}`+grid.y.values.map(y=>`<div class="heatLabel">${y}</div>`+grid.x.values.map(x=>{const cell=cellMap.get(`${x}|${y}`);if(!cell)return'<div class="heatLabel">—</div>';const value=cell.oos.excess,alpha=Math.min(.45,.06+Math.abs(value)*3);return`<button class="heatCell ${value<0?'negative':''} ${cell.x===best.x&&cell.y===best.y?'selected':''}" style="--heat:${alpha}" data-x="${x}" data-y="${y}" title="样本内 ${pct(cell.insample.excess)} · 样本外 ${pct(value)}">${pct(value)}</button>`}).join('')).join('');$('heatmap').querySelectorAll('.heatCell').forEach(button=>button.onclick=()=>{const cell=cellMap.get(`${button.dataset.x}|${button.dataset.y}`);activeParams[id]={...cell.params};render();$('validationStatus').className='validationStatus done';$('validationStatus').textContent=`已应用参数 ${paramText(id,cell.params)}；样本外热力图仅用于稳定性观察。`})}

async function runValidation(){if(!bars.length)return;const button=$('runValidation'),status=$('validationStatus'),config=cfg(),sample=bars.filter(x=>x.date>=config.start&&x.date<=config.end);if(sample.length<160){status.className='validationStatus';status.textContent='有效交易日不足160天，请扩大时间窗口。';return}button.disabled=true;button.classList.add('busy');button.lastElementChild.textContent='⟳';status.className='validationStatus busy';status.textContent='正在进行参数搜索、样本外验证和滚动回测…';await delay(40);const ratio=Math.min(.85,Math.max(.5,+$('splitRatio').value/100)),cut=Math.min(sample.length-60,Math.max(80,Math.floor(sample.length*ratio))),isStart=sample[0].date,isEnd=sample[cut-1].date,oosStart=sample[cut].date,oosEnd=sample.at(-1).date,id=config.strategy,ranked=optimize(bars,id,isStart,isEnd,currentAsset),best=ranked[0],oos=backtest(bars,id,{start:oosStart,end:oosEnd,params:best.params,asset:currentAsset}),cells=combinations(id).map(combo=>({x:combo.x,y:combo.y,params:combo.params,insample:backtest(bars,id,{start:isStart,end:isEnd,params:combo.params,asset:currentAsset}),oos:backtest(bars,id,{start:oosStart,end:oosEnd,params:combo.params,asset:currentAsset})}));const trainMonths=Math.max(6,+$('trainMonths').value),testMonths=Math.max(1,+$('testMonths').value),walk=[];let trainStart=config.start;while(walk.length<30){const trainEnd=previousDay(addMonths(trainStart,trainMonths)),testStart=addMonths(trainStart,trainMonths);if(testStart>config.end)break;const testEndCandidate=previousDay(addMonths(testStart,testMonths)),testEnd=testEndCandidate>config.end?config.end:testEndCandidate,trainCount=bars.filter(x=>x.date>=trainStart&&x.date<=trainEnd).length,testCount=bars.filter(x=>x.date>=testStart&&x.date<=testEnd).length;if(trainCount>=100&&testCount>=15){const selected=optimize(bars,id,trainStart,trainEnd,currentAsset)[0],tested=backtest(bars,id,{start:testStart,end:testEnd,params:selected.params,asset:currentAsset});walk.push({trainStart,trainEnd,testStart,testEnd,params:selected.params,result:tested})}trainStart=addMonths(trainStart,testMonths)}validationData={id,isStart,isEnd,oosStart,oosEnd,best,oos,cells,walk};const passWalk=walk.filter(x=>x.result.excess>0).length,median=[...walk].sort((a,b)=>a.result.excess-b.result.excess)[Math.floor(walk.length/2)]?.result.excess||0;$('validationSummary').innerHTML=[['样本内最优',paramText(id,best.params),`${isStart}—${isEnd}`],['样本内超额',pct(best.result.excess),`Calmar ${best.result.calmar.toFixed(2)}`],['样本外超额',pct(oos.excess),`${oosStart}—${oosEnd}`],['滚动通过率',walk.length?(passWalk/walk.length*100).toFixed(0)+'%':'—',`${passWalk}/${walk.length} 段 · 中位 ${pct(median)}`]].map((x,i)=>`<article class="validationCard"><span>${x[0]}</span><b class="${i===2?(oos.excess>=0?'up':'down'):''}">${x[1]}</b><small>${x[2]}</small></article>`).join('')+`<button class="run applyBest" id="applyBest"><span>应用样本内最优参数</span><b>↗</b></button>`;renderHeatmap(id,cells,best);$('walkTable').innerHTML=walk.length?'<div class="walkHead"><span>训练窗口</span><span>测试窗口</span><span>冻结参数</span><span>收益</span><span>基准</span><span>超额</span><span>回撤</span></div>'+walk.map(row=>`<div class="walkRow"><span>${row.trainStart.slice(2)}—${row.trainEnd.slice(2)}</span><span>${row.testStart.slice(2)}—${row.testEnd.slice(2)}</span><span><i class="pill">${paramText(id,row.params)}</i></span><strong class="${row.result.ret>=0?'up':'down'}">${pct(row.result.ret)}</strong><span>${pct(row.result.bret)}</span><strong class="${row.result.excess>=0?'up':'down'}">${pct(row.result.excess)}</strong><span class="down">${pct(row.result.dd)}</span></div>`).join(''):'<div class="empty">时间窗口不足以形成滚动测试。</div>';$('applyBest').onclick=()=>{activeParams[id]={...best.params};render();status.textContent=`已应用样本内最优参数 ${paramText(id,best.params)}。`};status.className='validationStatus done';status.textContent=`验证完成 · ${cells.length} 组参数 · ${walk.length} 个滚动窗口；样本外参数未参与选择。`;button.disabled=false;button.classList.remove('busy');button.lastElementChild.textContent='↗'}

function csvEscape(value){const text=String(value??'');return/[",\n]/.test(text)?`"${text.replaceAll('"','""')}"`:text}
function download(name,type,content){const blob=new Blob([content],{type}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=name;document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportCsv(){let rows;if(activeTrendResult&&window.currentResult?.model==='trend-core'){rows=[['日期','动作','成交价','数量','调整前仓位','调整后仓位','原因'],...window.currentResult.trades.map(x=>[x.date,x.action,x.price,x.shares,(x.from*100).toFixed(2)+'%',(x.to*100).toFixed(2)+'%',x.reason])]}else if(batchRows.some(x=>!x.error)){rows=[['标的','代码',...S.map(x=>x.name)]];for(const row of batchRows.filter(x=>!x.error))rows.push([row.asset.name,row.asset.code,...row.results.map(x=>(x.result.excess*100).toFixed(4)+'%')])}else{rows=[['入场日期','离场日期','买入价','卖出价','数量','收益率','离场原因'],...(window.currentResult?.trades||[]).map(x=>[x.ed,x.xd,x.ep,x.ex,x.shares,x.ret.toFixed(4)+'%',x.reason])]}download(`a-share-backtest-${new Date().toISOString().slice(0,10)}.csv`,'text/csv;charset=utf-8','\ufeff'+rows.map(row=>row.map(csvEscape).join(',')).join('\n'))}
function snapshot(){const result=window.currentResult;return{version:'V7',generatedAt:new Date().toISOString(),asset:currentAsset,config:cfg(),strategy:activeTrendResult?{id:'trend-core-v7',name:'30%回撤多模型择优'}:S.find(x=>x.id===cfg().strategy),params:activeTrendResult?.best.params||activeParams[cfg().strategy],benchmark:'100%买入持有',metrics:result&&{return:result.ret,benchmarkReturn:result.bret,excessReturn:result.excess,maxDrawdown:result.dd,benchmarkDrawdown:result.bmdd,sharpe:result.sharpe,calmar:result.calmar,turnover:result.turnover,blockedTrades:result.blocked},trades:result?.trades||[],batch:batchRows.filter(x=>!x.error).map(row=>({asset:row.asset,results:row.results.map(x=>({strategy:x.strategy.id,return:x.result.ret,excess:x.result.excess,drawdown:x.result.dd,calmar:x.result.calmar}))})),constraint:constraintData&&{objective:'positive return and excess return > 0 versus 100% buy-and-hold in training, out-of-sample and full periods, with drawdown cap',maxDrawdown:constraintData.maxDD,champion:constraintData.champion&&constraintSnapshotRow(constraintData.champion),nearest:constraintData.nearest&&constraintSnapshotRow(constraintData.nearest),top:(constraintData.top||[]).map(constraintSnapshotRow),rows:constraintRows.map(constraintSnapshotRow)},validation:validationData&&{strategy:validationData.id,inSample:[validationData.isStart,validationData.isEnd],outOfSample:[validationData.oosStart,validationData.oosEnd],selectedParams:validationData.best.params,inSampleExcess:validationData.best.result.excess,outOfSampleExcess:validationData.oos.excess,walkForward:validationData.walk.map(x=>({train:[x.trainStart,x.trainEnd],test:[x.testStart,x.testEnd],params:x.params,return:x.result.ret,excess:x.result.excess,drawdown:x.result.dd}))}}}
function constraintSnapshotRow(row){if(!row||!row.best)return{asset:row?.asset,error:row?.error};return{asset:row.asset,model:row.best.params.model||'trend-core',qualifies:row.qualifies,score:row.score,stability:row.stability&&{passes:row.stability.passes,total:row.stability.total},periods:{inSample:[row.isStart,row.isEnd],outOfSample:[row.oosStart,row.oosEnd]},params:row.best.params,inSample:{annualReturn:row.best.result.annual,return:row.best.result.ret,benchmarkReturn:row.best.result.bret,excessReturn:row.best.result.excess,maxDrawdown:row.best.result.dd},outOfSample:{annualReturn:row.oos.annual,return:row.oos.ret,benchmarkReturn:row.oos.bret,excessReturn:row.oos.excess,maxDrawdown:row.oos.dd,sharpe:row.oos.sharpe,calmar:row.oos.calmar},full:{return:row.full.ret,benchmarkReturn:row.full.bret,excessReturn:row.full.excess,maxDrawdown:row.full.dd}}}
function exportJson(){download(`a-share-backtest-${new Date().toISOString().slice(0,10)}.json`,'application/json;charset=utf-8',JSON.stringify(snapshot(),null,2))}

function init(){const today=new Date(),start=new Date(today);start.setFullYear(start.getFullYear()-5);$('start').value=start.toISOString().slice(0,10);$('end').value=today.toISOString().slice(0,10);$('strategy').innerHTML=S.map(x=>`<option value="${x.id}">${x.name}</option>`).join('');renderUniverse();document.querySelectorAll('.groupButtons button').forEach(button=>button.onclick=()=>setGroup(button.dataset.group));$('strategy').onchange=()=>{updateNote();render();resetValidation();validationData=null};$('riskMode').onchange=updateRiskUI;$('assetSelect').onchange=()=>{const option=$('assetSelect').selectedOptions[0],asset=ASSETS.find(x=>x.code===option.value)||{code:option.value,name:option.dataset.name,type:option.dataset.type};currentAsset={...asset};if(asset.type==='stock')$('symbol').value=asset.code;updateAssetMeta();loadCurrent(asset)};$('loadStock').onclick=()=>{const code=$('symbol').value.trim();if(!/^\d{6}$/.test(code)){alert('请输入6位A股代码');return}const asset={code,name:code,type:'stock',group:'自定义'};currentAsset=asset;$('assetSelect').selectedIndex=-1;updateAssetMeta(true);loadCurrent(asset)};$('run').onclick=()=>loadCurrent(currentAsset);$('runBatch').onclick=runBatch;$('cancelBatch').onclick=()=>{batchCancelled=true;$('batchStatus').textContent='正在停止剩余任务…'};$('runConstraint').onclick=runConstraint;$('runValidation').onclick=runValidation;$('exportCsv').onclick=exportCsv;$('exportJson').onclick=exportJson;$('printReport').onclick=()=>window.print();['capital','position','stop','take','fee','slip','atrMult','realistic'].forEach(id=>$(id).onchange=()=>render());updateRiskUI();loadCurrent(currentAsset)}

init();
